-- Run manually in Supabase SQL Editor as the table owner.
-- Source: sample-data.json. Five matches, ten sets; no schema changes.
-- Identity IDs are generated by PostgreSQL, not the sample m1-m5 IDs.
BEGIN;

-- Serialize imports and prevent concurrent changes while checking duplicates.
LOCK TABLE public.matches, public.match_sets
IN SHARE ROW EXCLUSIVE MODE;

DO $$
DECLARE
    r record;
    existing_match public.matches%ROWTYPE;
    target_match_id bigint;
    candidate_count bigint;
    actual_sets jsonb;
    expected_sets jsonb;
    actual_numbers integer[];
    a_wins integer;
    b_wins integer;
BEGIN
    FOR r IN
        SELECT * FROM (VALUES
            ('m1', DATE '2026-11-02', 'p1', 'p2', 'p2', '[[4,6],[3,6]]'::jsonb),
            ('m2', DATE '2026-11-05', 'p1', 'p3', 'p1', '[[6,3],[6,4]]'::jsonb),
            ('m3', DATE '2026-11-07', 'p3', 'p2', 'p3', '[[6,3],[6,4]]'::jsonb),
            ('m4', DATE '2026-11-09', 'p3', 'p1', 'p3', '[[6,3],[6,4]]'::jsonb),
            ('m5', DATE '2026-11-12', 'p1', 'p2', 'p1', '[[6,4],[6,3]]'::jsonb)
        ) AS source(sample_id, played_at, player_a_id, player_b_id, winner_id, sets)
    LOOP
        IF NOT EXISTS (SELECT 1 FROM public.players WHERE id = r.player_a_id)
           OR NOT EXISTS (SELECT 1 FROM public.players WHERE id = r.player_b_id)
        THEN
            RAISE EXCEPTION '%: required player is missing', r.sample_id;
        END IF;

        SELECT
            count(*) FILTER (WHERE (e.score ->> 0)::integer > (e.score ->> 1)::integer),
            count(*) FILTER (WHERE (e.score ->> 1)::integer > (e.score ->> 0)::integer)
        INTO a_wins, b_wins
        FROM jsonb_array_elements(r.sets) AS e(score);

        IF NOT ((r.winner_id = r.player_a_id AND a_wins = 2 AND b_wins = 0)
                OR (r.winner_id = r.player_b_id AND b_wins = 2 AND a_wins = 0))
        THEN
            RAISE EXCEPTION '%: winner does not match set scores', r.sample_id;
        END IF;

        SELECT count(*) INTO candidate_count
        FROM public.matches AS m
        WHERE m.played_at = r.played_at
          AND ((m.player_a_id = r.player_a_id AND m.player_b_id = r.player_b_id)
            OR (m.player_a_id = r.player_b_id AND m.player_b_id = r.player_a_id));

        IF candidate_count > 1 THEN
            RAISE EXCEPTION '%: multiple existing matches for this date and pair', r.sample_id;
        END IF;

        IF candidate_count = 1 THEN
            SELECT m.* INTO STRICT existing_match
            FROM public.matches AS m
            WHERE m.played_at = r.played_at
              AND ((m.player_a_id = r.player_a_id AND m.player_b_id = r.player_b_id)
                OR (m.player_a_id = r.player_b_id AND m.player_b_id = r.player_a_id));

            SELECT
                jsonb_agg(jsonb_build_array(s.player_a_games, s.player_b_games)
                          ORDER BY s.set_number),
                array_agg(s.set_number ORDER BY s.set_number)
            INTO actual_sets, actual_numbers
            FROM public.match_sets AS s
            WHERE s.match_id = existing_match.id;

            -- Compare in the stored match's A/B orientation.
            SELECT jsonb_agg(
                CASE WHEN existing_match.player_a_id = r.player_a_id THEN e.score
                     ELSE jsonb_build_array(e.score -> 1, e.score -> 0) END
                ORDER BY e.ordinality
            ) INTO expected_sets
            FROM jsonb_array_elements(r.sets) WITH ORDINALITY AS e(score, ordinality);

            IF existing_match.winner_id IS DISTINCT FROM r.winner_id
               OR actual_sets IS DISTINCT FROM expected_sets
               OR actual_numbers IS DISTINCT FROM ARRAY[1, 2]
            THEN
                RAISE EXCEPTION '%: existing match % conflicts with sample data',
                    r.sample_id, existing_match.id;
            END IF;
            CONTINUE;
        END IF;

        INSERT INTO public.matches (player_a_id, player_b_id, winner_id, played_at)
        VALUES (r.player_a_id, r.player_b_id, r.winner_id, r.played_at)
        RETURNING id INTO target_match_id;

        INSERT INTO public.match_sets
            (match_id, set_number, player_a_games, player_b_games)
        SELECT target_match_id, e.ordinality::integer,
               (e.score ->> 0)::integer, (e.score ->> 1)::integer
        FROM jsonb_array_elements(r.sets) WITH ORDINALITY AS e(score, ordinality);
    END LOOP;
END
$$;

COMMIT;
